    fun observeAll(): Flow<List<ServiceModel>> {
        return flowOf(services)
    }

    fun observeById(id: Int): Flow<ServiceModel?> {
        val service = services.firstOrNull { service -> service.id == id }
        return flowOf(service)
    }

    fun getById(id: Int): ServiceModel? {
        return services.firstOrNull { service -> service.id == id }
    }
}

private fun service(
    id: Int,
    category: ServiceCategory,
    price: Double,
    imageUrl: String,
    vararg localized: ServiceText,
) = ServiceModel(
    id = id,
    texts = listOf("en", "de", "es", "fr", "hi", "id", "pt", "ar").zip(localized).toMap(),
    serviceCategory = category,
    pricePerHour = price,
    imageUrl = imageUrl,
)

private fun t(name: String, description: String, vararg items: String) =
    ServiceText(name, description, items.toList())
